class TruckCourierStatusDialogController{constructor($mdDialog,DispatchData,toastrService,data){this._$mdDialog=$mdDialog;this._dispatchData=DispatchData;this._toastrService=toastrService;this.data=data}async refresh(courierId){try{const result=await this._dispatchData.truckCourierStatus(courierId);this.data=result.data[0]}catch(error){this._toastrService.showErrorToast(error.message)}}cancel(){this._$mdDialog.cancel()}}